	var X string
	var Xval string
	var S string
	var err error

	if len(args) != 2 {
		return shim.Error("Incorrect number of arguments. Expecting 3")
	}

	X = args[0]

	Xvalbytes, err := stub.GetState(X)
	if err != nil {
		return shim.Error("Failed to get state")
	}
	if Xvalbytes == nil {
		return shim.Error("Entity not found")
	}
	Xval, _ = string(Xvalbytes)

	S, err = args[1]
	if err != nil {
		return shim.Error("Invalid transaction amount, expecting a integer value")
	}

	// Validate S as an integer
	_, err = strconv.Atoi(S)
	if err != nil {
		return shim.Error("Invalid transaction amount, expecting a integer value")
	}

	// Use a transaction to ensure atomicity
	txid := stub.GetTxID()
	tx, err := stub.GetTransaction(txid)
	if err != nil {
		return shim.Error("Failed to get transaction")
	}

	// Update the state within the transaction
	err = stub.PutState(X, []byte(Xval+S))
	if err != nil {
		return shim.Error(err.Error())
	}

	return shim.Success(nil)
}
```

